/* Shared flat, filled controls in the m9 palette. */
/* Adapted from the older Motive9 controls, using the current brand palette. */
.m9-button {
  --button-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 10px;
  min-height: 44px;
  padding: 12px 20px;
  border: 1px solid transparent;
  border-radius: var(--button-radius);
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.3;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  user-select: none;
  cursor: pointer;
  box-shadow: none;
  transition:
    background-color 180ms ease-out,
    border-color 180ms ease-out,
    color 180ms ease-out;
}
.m9-button svg {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  pointer-events: none;
}
.m9-button-primary {
  background: var(--button-primary-bg, #fff21a);
  color: var(--button-primary-fg, #171717);
  border-color: color-mix(
    in srgb,
    var(--button-primary-bg, #fff21a) 80%,
    #171717
  );
}
.m9-button-primary:is(:hover, :focus-visible) {
  background: color-mix(in srgb, var(--button-primary-bg, #fff21a) 84%, #fff);
  color: var(--button-primary-fg, #171717);
}
.m9-button-secondary,
.m9-button-ghost {
  background: #fff;
  color: #171717;
  border-color: #dedede;
}
.m9-button-secondary:is(:hover, :focus-visible),
.m9-button-ghost:is(:hover, :focus-visible) {
  background: #f1f1f1;
  border-color: #9a9a9a;
}
.m9-button-destructive {
  background: #171717;
  color: #fff;
  border-color: #171717;
}
.m9-button:is(:active) {
  box-shadow: none;
}
.m9-button:focus-visible {
  outline: 2px solid var(--ring, #797100);
  outline-offset: 4px;
}
.m9-button:disabled,
.m9-button[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}
.m9-button-link {
  background: #171717;
  box-shadow: none;
  padding: 12px 20px;
  min-height: 44px;
  border: 0;
  color: #fff21a;
  text-decoration: none;
}
.m9-button-xs {
  min-height: 28px;
  padding: 6px 10px;
  font-size: 10px;
}
.m9-button-sm {
  min-height: 36px;
  padding: 8px 14px;
  font-size: 11px;
}
.m9-button-lg {
  min-height: 52px;
  padding: 16px 24px;
  font-size: 14px;
}
.m9-button-icon,
.m9-button-icon-xs,
.m9-button-icon-sm,
.m9-button-icon-lg {
  padding: 0;
  aspect-ratio: 1;
  border-radius: 50%;
}
.m9-button-icon {
  width: 40px;
  height: 40px;
  min-height: 40px;
}
.m9-button-icon-xs {
  width: 28px;
  height: 28px;
  min-height: 28px;
}
.m9-button-icon-sm {
  width: 36px;
  height: 36px;
  min-height: 36px;
}
.m9-button-icon-lg {
  width: 44px;
  height: 44px;
  min-height: 44px;
}
@media (prefers-reduced-motion: reduce) {
  .m9-button {
    transition: none;
  }
}
